// Token and environment handed to the OPSYS business engine (OPSYS-AI PLAN T0.10).
//
// One authentication: the engine authenticates its MCP callers with `OPSYS_MCP_JETON`, and the
// `mcp.servers.opsys_mN` headers generated by `src/opsys/openclaw.py` read the same variable
// (`Bearer ${OPSYS_MCP_JETON}`). The Gateway is the single owner of that secret: it reads it from
// its own environment, or generates it when absent, and only ever passes it to the engine
// through the child's environment (never argv, never a file, never a log line).
import { randomBytes as cryptoRandomBytes } from "node:crypto";
import { OPSYS_MCP_TOKEN_ENV } from "./opsys-metier-config.js";

/** `src/opsys/serveur_mcp.py` refuses a token shorter than this. */
const MIN_TOKEN_LENGTH = 24;
const GENERATED_TOKEN_BYTES = 32;
const TOKEN_PATTERN = /^\S+$/u;

function defaultRandomBytes(size: number): Buffer {
  return cryptoRandomBytes(size);
}

export type OpsysMcpTokenResult =
  | { ok: true; token: string; source: "env" | "generated" }
  | { ok: false; reason: string };

/**
 * Reads `OPSYS_MCP_JETON` from `env`, or generates a random 256-bit token when it is absent or
 * empty. A present but unusable value is refused: replacing it silently would leave the
 * Gateway's own MCP client and the engine with different secrets.
 */
export function resolveOpsysMcpToken(
  params: {
    env?: NodeJS.ProcessEnv;
    randomBytes?: (size: number) => Buffer;
  } = {},
): OpsysMcpTokenResult {
  const env = params.env ?? process.env;
  const existing = env[OPSYS_MCP_TOKEN_ENV];
  if (existing === undefined || existing === "") {
    const bytes = (params.randomBytes ?? defaultRandomBytes)(GENERATED_TOKEN_BYTES);
    return { ok: true, token: bytes.toString("hex"), source: "generated" };
  }
  if (existing.length < MIN_TOKEN_LENGTH || !TOKEN_PATTERN.test(existing)) {
    return {
      ok: false,
      reason: `${OPSYS_MCP_TOKEN_ENV} must be at least ${String(MIN_TOKEN_LENGTH)} characters without whitespace`,
    };
  }
  return { ok: true, token: existing, source: "env" };
}

// The engine gets what a Python process needs to run and to reach its own services, not the
// Gateway's secrets (`OPENCLAW_*`, provider API keys, channel tokens). Anything else it needs
// goes through the `env` key of `opsys/metier.json`.
const PASSTHROUGH_NAMES = new Set([
  "ALL_PROXY",
  "APPDATA",
  "COMSPEC",
  "CURL_CA_BUNDLE",
  "HOME",
  "HTTPS_PROXY",
  "HTTP_PROXY",
  "LANG",
  "LANGUAGE",
  "LOCALAPPDATA",
  "LOGNAME",
  "NO_PROXY",
  "PATH",
  "PATHEXT",
  "REQUESTS_CA_BUNDLE",
  "SHELL",
  "SSL_CERT_DIR",
  "SSL_CERT_FILE",
  "SYSTEMROOT",
  "TEMP",
  "TMP",
  "TMPDIR",
  "TZ",
  "USER",
  "USERNAME",
  "USERPROFILE",
  "WINDIR",
]);
const PASSTHROUGH_PREFIXES = ["LC_", "LITELLM_", "OPSYS_", "PYTHON", "UV_", "XDG_"];

function isPassedThrough(name: string): boolean {
  const upper = name.toUpperCase();
  return PASSTHROUGH_NAMES.has(upper) || PASSTHROUGH_PREFIXES.some((prefix) => upper.startsWith(prefix));
}

/**
 * Environment of the engine process: the passthrough subset of `base`, unbuffered Python output
 * (so the journal relay sees lines as they happen), then the operator's `extra`, then the token,
 * which nothing can override.
 */
export function buildOpsysMetierChildEnv(params: {
  base: NodeJS.ProcessEnv;
  extra: Readonly<Record<string, string>>;
  token: string;
}): Record<string, string> {
  const env: Record<string, string> = {};
  for (const [name, value] of Object.entries(params.base)) {
    if (value !== undefined && isPassedThrough(name)) {
      env[name] = value;
    }
  }
  env.PYTHONUNBUFFERED = "1";
  Object.assign(env, params.extra);
  env[OPSYS_MCP_TOKEN_ENV] = params.token;
  return env;
}

/**
 * Environment of the engine's CLI when the operator runs `opsys metier <command>` (PLAN T0.7
 * lot 2). Same passthrough as the supervised engine: what Python needs and the `OPSYS_*` /
 * `LITELLM_*` settings, never the Gateway's own `OPENCLAW_*` variables or provider keys. Three
 * differences from `buildOpsysMetierChildEnv`:
 * - `extra` (the `env` key of `metier.json`) only holds DEFAULTS here: the caller's environment
 *   wins, so `OPSYS_HOME=/autre opsys metier instance restaurer ...` reaches the engine as typed
 *   instead of being silently redirected to the installed instance;
 * - no token is added: an `OPSYS_MCP_JETON` already in the environment (the instance `.env` the
 *   Gateway also reads) passes through by its prefix, as it did with the old `opsys` command;
 * - on Windows, Python writes UTF-8 even when its output is redirected (in cp1252 an arrow in a
 *   message makes `print` fail).
 */
export function buildOpsysMetierCliEnv(params: {
  base: NodeJS.ProcessEnv;
  extra: Readonly<Record<string, string>>;
  platform?: NodeJS.Platform;
}): Record<string, string> {
  const env: Record<string, string> = { ...params.extra };
  for (const [name, value] of Object.entries(params.base)) {
    if (value !== undefined && isPassedThrough(name)) {
      env[name] = value;
    }
  }
  if ((params.platform ?? process.platform) === "win32") {
    env.PYTHONUTF8 = "1";
  }
  return env;
}
